css:
@keyframes fadeIn{from{opacity:0}to{opacity:1}}
@keyframes fadeOut{to{opacity:0}}
@keyframes rise{from{opacity:0;transform:translateY(50px)}to{opacity:1;transform:none}}
@keyframes riseBlur{from{opacity:0;transform:translateY(60px);filter:blur(16px)}to{opacity:1;transform:none;filter:blur(0)}}
@keyframes liftOut{to{opacity:0;transform:translateY(-120px) scale(.94);filter:blur(14px)}}
@keyframes pop{0%{opacity:0;transform:scale(0) rotate(-120deg)}70%{opacity:1;transform:scale(1.1) rotate(6deg)}100%{opacity:1;transform:none}}
@keyframes wipe{from{clip-path:inset(0 100% 0 0)}to{clip-path:inset(0 -10% 0 0)}}
@keyframes drift{0%{transform:translate(0,0) scale(1)}50%{transform:translate(140px,-90px) scale(1.18)}100%{transform:translate(-70px,70px) scale(.94)}}
@keyframes sweep{from{transform:scaleX(0)}to{transform:scaleX(1)}}
.bg{overflow:hidden}
.orb{position:absolute;border-radius:50%;filter:blur(120px);animation:drift 24s ease-in-out 0s both}
.grid{position:absolute;inset:0;background-image:linear-gradient(rgba(255,255,255,.035) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.035) 1px,transparent 1px);background-size:80px 80px;-webkit-mask-image:radial-gradient(ellipse at center,#000 30%,transparent 75%);mask-image:radial-gradient(ellipse at center,#000 30%,transparent 75%)}
.shot{position:absolute;border-radius:22px;overflow:hidden;border:1px solid rgba(255,255,255,.12);box-shadow:0 50px 140px rgba(0,0,0,.65),0 0 0 1px rgba(0,0,0,.4)}
.shot img{display:block;width:100%;height:100%;object-fit:cover;object-position:top left}
.h{font-family:var(--font-headline);font-weight:900;letter-spacing:-.045em;line-height:.95;color:var(--fg);margin:0}
.p{font-size:38px;color:var(--muted);line-height:1.35;margin:0}

.fbg{background:linear-gradient(180deg,#0B1210,var(--bg))}
.fbg .stripes{position:absolute;inset:-200px;background:repeating-linear-gradient(-45deg,rgba(184,243,90,.025) 0 40px,transparent 40px 80px);animation:belt 24s linear 0s both}
@keyframes belt{from{transform:translateX(0)}to{transform:translateX(-226px)}}
.o1{width:700px;height:700px;background:#B8F35A;left:-240px;bottom:-320px;opacity:.16}
.o2{width:700px;height:700px;background:#2DD4BF;right:-260px;top:-300px;opacity:.16;animation-direction:reverse}
.mono{font-family:ui-monospace,"DejaVu Sans Mono",monospace;letter-spacing:.02em}

.line{animation:fadeOut .5s ease 6.3s forwards}
.line .top{position:absolute;left:0;right:0;top:170px;text-align:center}
.line .eyebrow{font-size:28px;color:var(--accent);letter-spacing:.35em;text-transform:uppercase;animation:fadeIn .6s ease .1s both}
.line .h{font-size:132px;margin-top:22px}
.line .h .l{display:inline-block;animation:drop .7s cubic-bezier(.16,1,.3,1) both}
@keyframes drop{from{opacity:0;transform:translateY(-80px) rotateX(80deg)}to{opacity:1;transform:none}}
.track{position:absolute;left:160px;right:160px;top:640px;height:6px;border-radius:3px;background:rgba(255,255,255,.1)}
.track .fill{position:absolute;inset:0;border-radius:3px;background:linear-gradient(90deg,#2DD4BF,var(--accent));transform-origin:left;animation:sweep 3.4s cubic-bezier(.45,0,.2,1) 1.6s both;box-shadow:0 0 24px rgba(184,243,90,.6)}
.node{position:absolute;top:640px;width:0;height:0}
.node .dot{position:absolute;left:-34px;top:-31px;width:68px;height:68px;border-radius:20px;background:#121A17;border:2px solid rgba(255,255,255,.18);display:grid;place-items:center;color:var(--muted);animation:nodeIn .5s cubic-bezier(.16,1,.3,1) both,lit .4s ease both}
.node .lab{position:absolute;left:-120px;width:240px;top:62px;text-align:center;font-size:30px;font-weight:600;color:var(--muted);animation:fadeIn .5s ease both,litText .4s ease both}
@keyframes nodeIn{from{opacity:0;transform:scale(.4)}to{opacity:1;transform:none}}
@keyframes lit{to{background:var(--accent);border-color:var(--accent);color:#0B1408;box-shadow:0 0 50px rgba(184,243,90,.55)}}
@keyframes litText{to{color:var(--fg)}}
.packet{position:absolute;top:640px;left:160px;width:26px;height:26px;margin:-10px 0 0 -13px;border-radius:50%;background:#fff;box-shadow:0 0 30px 8px rgba(184,243,90,.9);animation:travel 3.4s cubic-bezier(.45,0,.2,1) 1.6s both}
@keyframes travel{from{left:160px;opacity:1}96%{opacity:1}to{left:1760px;opacity:0}}
.ends{position:absolute;left:160px;right:160px;top:830px;display:flex;justify-content:space-between;font-size:34px}
.ends span{padding:14px 26px;border-radius:14px;border:1px dashed rgba(255,255,255,.25);color:var(--fg);animation:rise .6s cubic-bezier(.16,1,.3,1) both}
.ends span.out{border-style:solid;border-color:var(--accent);color:var(--accent)}

.run{animation:fadeOut .5s ease 6.1s forwards}
.run .shot{left:120px;top:250px;width:1180px;height:740px;animation:fromLeft 1.2s cubic-bezier(.16,1,.3,1) .05s both}
.run .shot img{transform-origin:30% 30%;animation:kb 6.2s ease-in-out 1s both}
@keyframes fromLeft{from{opacity:0;transform:perspective(2400px) rotateY(24deg) translateX(-260px)}to{opacity:1;transform:perspective(2400px) rotateY(9deg)}}
@keyframes kb{from{transform:scale(1)}to{transform:scale(1.45) translate(4%,3%)}}
.run .copy{position:absolute;left:1360px;top:250px;width:470px}
.run .h{font-size:84px;animation:riseBlur .9s cubic-bezier(.16,1,.3,1) .25s both}
.run .h em{font-style:normal;color:var(--accent)}
.run .p{font-size:34px;margin-top:30px;animation:rise .8s cubic-bezier(.16,1,.3,1) .6s both}
.run .head{position:absolute;left:120px;top:80px;display:flex;gap:16px}
.chip{display:flex;align-items:center;gap:12px;padding:14px 24px;border-radius:14px;background:rgba(17,25,22,.92);border:1px solid rgba(184,243,90,.35);font-size:28px;font-weight:600;color:var(--fg);animation:chipIn .5s cubic-bezier(.16,1,.3,1) both}
.chip svg{color:var(--accent)}
@keyframes chipIn{from{opacity:0;transform:translateY(-30px) scale(.8)}to{opacity:1;transform:none}}

.dirs{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:64px;animation:fadeOut .45s ease 3.6s forwards}
.dirs .h{font-size:96px;animation:riseBlur .8s cubic-bezier(.16,1,.3,1) .05s both}
.cards{display:flex;gap:44px}
.card{width:420px;height:420px;border-radius:30px;padding:40px;display:flex;flex-direction:column;justify-content:flex-end;gap:12px;color:#fff;animation:flip .9s cubic-bezier(.16,1,.3,1) both,dim .5s ease 2.2s forwards;position:relative;overflow:hidden}
.card b{font-size:56px;font-weight:850;letter-spacing:-.03em}
.card small{font-size:26px;opacity:.85}
.card .ui{position:absolute;left:40px;right:40px;top:40px;display:flex;flex-direction:column;gap:14px}
.card .ui i{display:block;height:22px;border-radius:11px;background:rgba(255,255,255,.28)}
.card .ui i:nth-child(1){width:60%;height:34px}.card .ui i:nth-child(3){width:80%}.card .ui i:nth-child(4){width:45%}
.c1{background:linear-gradient(160deg,#5B7FA6,#2F4A6B)}
.c2{background:linear-gradient(160deg,#E5484D,#9B1C24);animation:flip .9s cubic-bezier(.16,1,.3,1) both,pick .6s cubic-bezier(.16,1,.3,1) 2.1s forwards!important}
.c3{background:linear-gradient(160deg,#F2A93B,#B86A0E)}
@keyframes flip{from{opacity:0;transform:perspective(1600px) rotateY(-85deg) translateX(-100px)}to{opacity:1;transform:perspective(1600px) rotateY(0)}}
@keyframes dim{to{opacity:.3;transform:scale(.92)}}
@keyframes pick{to{transform:scale(1.1);box-shadow:0 0 0 6px var(--accent),0 0 120px rgba(184,243,90,.4)}}
.picked{position:absolute;right:28px;top:28px;width:70px;height:70px;border-radius:50%;background:var(--accent);color:#0B1408;display:grid;place-items:center;animation:pop .6s cubic-bezier(.16,1,.3,1) 2.4s both}

.demo{animation:fadeOut .45s ease 3.6s forwards}
.demo .shot{left:240px;top:200px;width:1440px;height:810px;animation:upIn 1.1s cubic-bezier(.16,1,.3,1) 0s both}
.demo .shot img{transform-origin:40% 30%;animation:kb 4s ease-in-out .8s both}
@keyframes upIn{from{opacity:0;transform:translateY(240px) scale(.92)}to{opacity:1;transform:none}}
.demo .top{position:absolute;left:0;right:0;top:70px;text-align:center}
.demo .h{font-size:84px;animation:riseBlur .8s cubic-bezier(.16,1,.3,1) .2s both}

.trace{animation:fadeOut .45s ease 3.1s forwards}
.trace .shot{right:110px;top:150px;width:1100px;height:704px;animation:fromRight 1.1s cubic-bezier(.16,1,.3,1) 0s both}
@keyframes fromRight{from{opacity:0;transform:perspective(2400px) rotateY(-24deg) translateX(260px)}to{opacity:1;transform:perspective(2400px) rotateY(-9deg)}}
.trace .copy{position:absolute;left:120px;top:300px;width:620px}
.trace .h{font-size:96px;animation:riseBlur .8s cubic-bezier(.16,1,.3,1) .15s both}
.stat{display:flex;gap:40px;margin-top:44px}
.stat div{animation:rise .7s cubic-bezier(.16,1,.3,1) both}
.stat b{display:block;font-size:84px;font-weight:900;color:var(--accent);letter-spacing:-.04em}
.stat span{font-size:28px;color:var(--muted)}

.end{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:40px}
.logo{display:flex;align-items:center;gap:44px}
.mark{width:200px;height:200px;border-radius:52px;background:linear-gradient(135deg,#D7FF8A,#B8F35A 45%,#2DD4BF);display:grid;place-items:center;color:#0B1408;animation:pop 1s cubic-bezier(.16,1,.3,1) .15s both}
.word{font-size:210px;font-weight:900;letter-spacing:-.06em;color:var(--fg);animation:wipe 1s cubic-bezier(.7,0,.2,1) .7s both}
.end .p{font-size:46px;animation:rise .8s cubic-bezier(.16,1,.3,1) 1.5s both}
.end .p b{color:var(--accent);font-weight:700}
